CREATE TABLE organization_departments (id VARCHAR(36) PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(128) NOT NULL, parent_id VARCHAR(36) NULL, active BOOLEAN NOT NULL, archived BOOLEAN NOT NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_organization_department_parent FOREIGN KEY(parent_id) REFERENCES organization_departments(id) ON DELETE RESTRICT);
CREATE INDEX ix_organization_departments_parent ON organization_departments(parent_id);
CREATE TABLE organization_positions (id VARCHAR(36) PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(128) NOT NULL, active BOOLEAN NOT NULL, archived BOOLEAN NOT NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL);
CREATE TABLE organization_account_departments (account_id VARCHAR(36) PRIMARY KEY, department_id VARCHAR(36) NOT NULL, assigned BOOLEAN NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_organization_ad_department FOREIGN KEY(department_id) REFERENCES organization_departments(id) ON DELETE RESTRICT);
CREATE INDEX ix_organization_account_departments_department ON organization_account_departments(department_id);
CREATE TABLE organization_account_positions (account_id VARCHAR(36) NOT NULL, position_id VARCHAR(36) NOT NULL, assigned BOOLEAN NOT NULL, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(account_id, position_id), CONSTRAINT fk_organization_ap_position FOREIGN KEY(position_id) REFERENCES organization_positions(id) ON DELETE RESTRICT);
CREATE INDEX ix_organization_account_positions_position ON organization_account_positions(position_id);
